// Prepara los datos del email de seguimiento.
const b = $json;
const issues = Array.isArray(b.top_issues) ? b.top_issues : JSON.parse(b.top_issues || '[]');
const first = issues[0];
const host = String(b.audited_url).replace(/^https?:\/\//, '').replace(/\/$/, '');
const nombre = String(b.name || '').trim().split(/\s+/)[0] || 'hola';
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const destacado = first
  ? `<p>Lo más importante que vimos: <b>${esc(first.label)}</b> (${esc(first.category)}). ${esc(first.message)}</p>`
  : `<p>No vimos errores graves, pero sí <b>${Number(b.warnings) || 0} aspectos a mejorar</b> que pueden darte más visibilidad en Google y en los buscadores con IA.</p>`;
return { json: { ID: b.id, Email: b.email, Nombre: nombre, Host: host, Nota: b.score === null ? '' : String(Number(b.score)), Destacado: destacado, Informe: b.report_url || 'https://auditoria.agenticsprojects.com' } };
